-- USIE initial schema.
--
-- Conventions
--   * Every tenant-owned table carries organization_id; every query in the
--     application filters on it. Composite foreign keys (organization_id, id)
--     make it impossible for a row to reference another tenant's row.
--   * Primary keys are UUIDs generated by the database.
--   * Timestamps are timestamptz in UTC.
--   * Migrations are forward-only and applied in filename order.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE organizations (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    slug        text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'),
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email          text NOT NULL CHECK (length(email) BETWEEN 3 AND 320),
    display_name   text NOT NULL DEFAULT '',
    password_hash  text NOT NULL,
    disabled       boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));

CREATE TABLE memberships (
    organization_id  uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    user_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role             text NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'viewer')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (organization_id, user_id)
);
CREATE INDEX memberships_user_idx ON memberships (user_id);

-- Browser sessions. Only a SHA-256 of the session token is stored.
CREATE TABLE sessions (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    token_hash       bytea NOT NULL UNIQUE,
    user_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    organization_id  uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    csrf_token       text NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    expires_at       timestamptz NOT NULL,
    last_seen_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expiry_idx ON sessions (expires_at);

-- API tokens for programmatic access. Only a SHA-256 of the token is stored.
CREATE TABLE api_tokens (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    user_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name             text NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    token_hash       bytea NOT NULL UNIQUE,
    token_prefix     text NOT NULL,
    role             text NOT NULL CHECK (role IN ('admin', 'member', 'viewer')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    last_used_at     timestamptz,
    expires_at       timestamptz,
    revoked_at       timestamptz
);
CREATE INDEX api_tokens_org_idx ON api_tokens (organization_id);

CREATE TABLE workspaces (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name             text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    created_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (organization_id, id),
    UNIQUE (organization_id, name)
);

CREATE TABLE repositories (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    workspace_id     uuid NOT NULL,
    name             text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    -- 'git': cloned over HTTPS; 'local': a directory under an allowed root on
    -- the worker; 'upload': ZIP archives uploaded through the API.
    source_kind      text NOT NULL CHECK (source_kind IN ('git', 'local', 'upload')),
    -- Remote URL or local path. Never contains credentials.
    source_location  text NOT NULL DEFAULT '',
    default_ref      text NOT NULL DEFAULT '',
    created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (organization_id, id),
    UNIQUE (workspace_id, name),
    FOREIGN KEY (organization_id, workspace_id) REFERENCES workspaces (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX repositories_org_idx ON repositories (organization_id, created_at DESC);

-- One immutable analyzed state of a repository. The knowledge graph
-- snapshot of a version is identified by the version id.
CREATE TABLE repository_versions (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    repository_id    uuid NOT NULL,
    sequence         integer NOT NULL,
    status           text NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending', 'analyzing', 'ready', 'failed', 'cancelled')),
    requested_ref    text NOT NULL DEFAULT '',
    commit_sha       text NOT NULL DEFAULT '',
    branch           text NOT NULL DEFAULT '',
    -- SHA-256 over the sorted (path, content hash) list: identical trees
    -- have identical hashes regardless of how they were imported.
    tree_hash        text NOT NULL DEFAULT '',
    parent_version_id uuid REFERENCES repository_versions(id) ON DELETE SET NULL,
    -- Blob key of an uploaded archive awaiting import (upload sources only).
    upload_key       text NOT NULL DEFAULT '',
    stats            jsonb NOT NULL DEFAULT '{}',
    error            text NOT NULL DEFAULT '',
    created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    analyzed_at      timestamptz,
    UNIQUE (organization_id, id),
    UNIQUE (repository_id, sequence),
    FOREIGN KEY (organization_id, repository_id) REFERENCES repositories (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX repository_versions_repo_idx ON repository_versions (repository_id, sequence DESC);

CREATE TABLE commits (
    organization_id  uuid NOT NULL,
    repository_id    uuid NOT NULL,
    sha              text NOT NULL,
    parents          text[] NOT NULL DEFAULT '{}',
    author_name      text NOT NULL DEFAULT '',
    author_email     text NOT NULL DEFAULT '',
    authored_at      timestamptz,
    committed_at     timestamptz,
    subject          text NOT NULL DEFAULT '',
    PRIMARY KEY (repository_id, sha),
    FOREIGN KEY (organization_id, repository_id) REFERENCES repositories (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX commits_repo_time_idx ON commits (repository_id, committed_at DESC);

CREATE TABLE branches (
    organization_id  uuid NOT NULL,
    repository_id    uuid NOT NULL,
    name             text NOT NULL,
    head_sha         text NOT NULL,
    is_default       boolean NOT NULL DEFAULT false,
    updated_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (repository_id, name),
    FOREIGN KEY (organization_id, repository_id) REFERENCES repositories (organization_id, id) ON DELETE CASCADE
);

CREATE TABLE source_files (
    organization_id  uuid NOT NULL,
    version_id       uuid NOT NULL,
    path             text NOT NULL,
    content_hash     text NOT NULL,
    size_bytes       bigint NOT NULL,
    language         text NOT NULL DEFAULT '',
    -- source | test | config | documentation | build | data | asset | binary
    category         text NOT NULL,
    encoding         text NOT NULL DEFAULT '',
    is_generated     boolean NOT NULL DEFAULT false,
    is_vendored      boolean NOT NULL DEFAULT false,
    -- Whether the content is retained in the blob store.
    content_stored   boolean NOT NULL DEFAULT false,
    -- parsed | parsed_with_errors | unsupported | skipped | failed
    parse_status     text NOT NULL,
    parse_detail     text NOT NULL DEFAULT '',
    -- unchanged | modified | added, relative to the parent version.
    change           text NOT NULL DEFAULT 'added',
    line_count       integer NOT NULL DEFAULT 0,
    symbol_count     integer NOT NULL DEFAULT 0,
    diagnostic_count integer NOT NULL DEFAULT 0,
    analyzed_at      timestamptz,
    PRIMARY KEY (version_id, path),
    FOREIGN KEY (organization_id, version_id) REFERENCES repository_versions (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX source_files_hash_idx ON source_files (organization_id, content_hash);

-- Parse cache index. The IR itself lives in the blob store; this table
-- records that an analysis exists for (content, language, parser).
-- Scoped per organization so tenants never observe each other's content
-- through cache hits.
CREATE TABLE file_analyses (
    organization_id     uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    content_hash        text NOT NULL,
    language            text NOT NULL,
    parser_fingerprint  text NOT NULL,
    status              text NOT NULL CHECK (status IN ('ok', 'error')),
    error_code          text NOT NULL DEFAULT '',
    error_message       text NOT NULL DEFAULT '',
    symbol_count        integer NOT NULL DEFAULT 0,
    diagnostic_count    integer NOT NULL DEFAULT 0,
    created_at          timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (organization_id, content_hash, language, parser_fingerprint)
);

-- Dependencies declared in manifests.
CREATE TABLE dependencies (
    organization_id  uuid NOT NULL,
    version_id       uuid NOT NULL,
    manifest_path    text NOT NULL,
    ecosystem        text NOT NULL,
    name             text NOT NULL,
    requirement      text NOT NULL DEFAULT '',
    scope            text NOT NULL DEFAULT 'runtime',
    PRIMARY KEY (version_id, manifest_path, ecosystem, name, scope),
    FOREIGN KEY (organization_id, version_id) REFERENCES repository_versions (organization_id, id) ON DELETE CASCADE
);

-- Knowledge graph. PostgreSQL is the system of record; any graph database
-- is a derived, rebuildable projection (see ADR 0003).
CREATE TABLE graph_nodes (
    organization_id  uuid NOT NULL,
    version_id       uuid NOT NULL,
    id               integer NOT NULL,
    -- Stable across versions: repo, dir:<path>, file:<path>,
    -- sym:<path>#<qualified name>, ext:<ecosystem>:<name>.
    key              text NOT NULL,
    kind             text NOT NULL,
    name             text NOT NULL,
    qualified_name   text NOT NULL DEFAULT '',
    path             text NOT NULL DEFAULT '',
    start_line       integer NOT NULL DEFAULT 0,
    end_line         integer NOT NULL DEFAULT 0,
    signature        text NOT NULL DEFAULT '',
    doc              text NOT NULL DEFAULT '',
    exported         boolean NOT NULL DEFAULT false,
    attrs            jsonb NOT NULL DEFAULT '{}',
    PRIMARY KEY (version_id, id),
    UNIQUE (version_id, key),
    FOREIGN KEY (organization_id, version_id) REFERENCES repository_versions (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX graph_nodes_kind_idx ON graph_nodes (version_id, kind);
CREATE INDEX graph_nodes_path_idx ON graph_nodes (version_id, path, start_line);
CREATE INDEX graph_nodes_name_idx ON graph_nodes (version_id, lower(name) text_pattern_ops);

CREATE TABLE graph_relationships (
    organization_id  uuid NOT NULL,
    version_id       uuid NOT NULL,
    src              integer NOT NULL,
    dst              integer NOT NULL,
    kind             text NOT NULL,
    confidence       text NOT NULL CHECK (confidence IN ('confirmed', 'probable', 'inferred', 'unknown')),
    -- Provenance: the rule that produced the relationship and where its
    -- strongest evidence is.
    rule             text NOT NULL,
    evidence_path    text NOT NULL DEFAULT '',
    evidence_line    integer NOT NULL DEFAULT 0,
    occurrences      integer NOT NULL DEFAULT 1,
    PRIMARY KEY (version_id, src, dst, kind),
    FOREIGN KEY (version_id, src) REFERENCES graph_nodes (version_id, id) ON DELETE CASCADE,
    FOREIGN KEY (version_id, dst) REFERENCES graph_nodes (version_id, id) ON DELETE CASCADE
);
CREATE INDEX graph_relationships_dst_idx ON graph_relationships (version_id, dst, kind);

-- Symbols are graph nodes; this view gives them their conventional name.
CREATE VIEW symbols AS
    SELECT organization_id, version_id, id, key, kind, name, qualified_name, path,
           start_line, end_line, signature, doc, exported, attrs
    FROM graph_nodes
    WHERE kind IN ('function', 'method', 'class', 'interface', 'type', 'variable', 'namespace');

-- Every syntactic reference the resolver examined, including the ones it
-- could not resolve (target_key empty, reason set).
CREATE TABLE symbol_references (
    organization_id  uuid NOT NULL,
    version_id       uuid NOT NULL,
    seq              integer NOT NULL,
    path             text NOT NULL,
    line             integer NOT NULL,
    col              integer NOT NULL,
    kind             text NOT NULL,
    text             text NOT NULL,
    source_key       text NOT NULL,
    outcome          text NOT NULL CHECK (outcome IN ('resolved', 'external', 'builtin', 'unresolved')),
    confidence       text NOT NULL,
    target_key       text NOT NULL DEFAULT '',
    rule             text NOT NULL,
    reason           text NOT NULL DEFAULT '',
    PRIMARY KEY (version_id, seq),
    FOREIGN KEY (organization_id, version_id) REFERENCES repository_versions (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX symbol_references_path_idx ON symbol_references (version_id, path, line);
CREATE INDEX symbol_references_outcome_idx ON symbol_references (version_id, outcome);
CREATE INDEX symbol_references_target_idx ON symbol_references (version_id, target_key) WHERE target_key <> '';

CREATE TABLE workers (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    hostname         text NOT NULL,
    pid              integer NOT NULL,
    version          text NOT NULL DEFAULT '',
    capabilities     jsonb NOT NULL DEFAULT '{}',
    status           text NOT NULL DEFAULT 'idle' CHECK (status IN ('idle', 'busy', 'stopped')),
    started_at       timestamptz NOT NULL DEFAULT now(),
    last_heartbeat_at timestamptz NOT NULL DEFAULT now(),
    jobs_completed   integer NOT NULL DEFAULT 0,
    jobs_failed      integer NOT NULL DEFAULT 0
);

CREATE TABLE analysis_jobs (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    repository_id    uuid NOT NULL,
    version_id       uuid NOT NULL,
    kind             text NOT NULL CHECK (kind IN ('analyze_version')),
    status           text NOT NULL DEFAULT 'queued'
                     CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled')),
    priority         integer NOT NULL DEFAULT 0,
    attempts         integer NOT NULL DEFAULT 0,
    max_attempts     integer NOT NULL DEFAULT 3,
    run_after        timestamptz NOT NULL DEFAULT now(),
    cancel_requested boolean NOT NULL DEFAULT false,
    worker_id        uuid REFERENCES workers(id) ON DELETE SET NULL,
    lease_expires_at timestamptz,
    stage            text NOT NULL DEFAULT '',
    progress         jsonb NOT NULL DEFAULT '{}',
    error            text NOT NULL DEFAULT '',
    created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    started_at       timestamptz,
    finished_at      timestamptz,
    updated_at       timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (organization_id, version_id) REFERENCES repository_versions (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX analysis_jobs_claim_idx ON analysis_jobs (priority DESC, created_at) WHERE status = 'queued';
CREATE INDEX analysis_jobs_lease_idx ON analysis_jobs (lease_expires_at) WHERE status = 'running';
CREATE INDEX analysis_jobs_org_idx ON analysis_jobs (organization_id, created_at DESC);

-- Append-only audit trail. The application role needs only INSERT/SELECT.
CREATE TABLE audit_events (
    id               bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    organization_id  uuid REFERENCES organizations(id) ON DELETE CASCADE,
    actor_user_id    uuid,
    actor_kind       text NOT NULL DEFAULT 'user',
    action           text NOT NULL,
    target_type      text NOT NULL DEFAULT '',
    target_id        text NOT NULL DEFAULT '',
    outcome          text NOT NULL DEFAULT 'success',
    ip               text NOT NULL DEFAULT '',
    request_id       text NOT NULL DEFAULT '',
    detail           jsonb NOT NULL DEFAULT '{}',
    created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_events_org_idx ON audit_events (organization_id, id DESC);
